<?php $editando = is_array($editar ?? null); ?>
<section class="page-head"><div><span class="badge">Cadastro</span><h1>Produtos</h1><p>Cadastre os materiais controlados pelo almoxarifado.</p></div><a class="button secondary" href="?route=/dashboard">Voltar ao painel</a></section>
<?php if (!empty($flash)): ?><div class="alert <?= ($flash['tipo'] ?? '') === 'sucesso' ? 'success' : 'error' ?>"><?= htmlspecialchars((string) ($flash['mensagem'] ?? ''), ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?>
<section class="crud-layout products-layout"><article class="card form-card"><h2><?= $editando ? 'Editar produto' : 'Novo produto' ?></h2><form method="post" action="?route=/produtos/salvar"><input type="hidden" name="id" value="<?= (int) ($editar['id'] ?? 0) ?>"><label for="nome">Nome do produto</label><input id="nome" name="nome" maxlength="160" required value="<?= htmlspecialchars((string) ($editar['nome'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"><label for="categoria_id">Categoria</label><select id="categoria_id" name="categoria_id"><option value="0">Sem categoria</option><?php foreach ($categorias as $categoria): ?><?php if (!$categoria['ativo'] && (int) ($editar['categoria_id'] ?? 0) !== (int) $categoria['id']) continue; ?><option value="<?= (int) $categoria['id'] ?>" <?= (int) ($editar['categoria_id'] ?? 0) === (int) $categoria['id'] ? 'selected' : '' ?>><?= htmlspecialchars($categoria['nome'], ENT_QUOTES, 'UTF-8') ?><?= !$categoria['ativo'] ? ' (inativa)' : '' ?></option><?php endforeach; ?></select><div class="form-grid two"><div><label for="unidade_medida">Unidade de medida</label><input id="unidade_medida" name="unidade_medida" maxlength="30" placeholder="UN, CX, PCT..." value="<?= htmlspecialchars((string) ($editar['unidade_medida'] ?? 'UN'), ENT_QUOTES, 'UTF-8') ?>"></div><div><label for="estoque_minimo">Estoque mínimo</label><input id="estoque_minimo" name="estoque_minimo" inputmode="decimal" value="<?= htmlspecialchars((string) ($editar['estoque_minimo'] ?? '0'), ENT_QUOTES, 'UTF-8') ?>"></div></div><label for="descricao">Descrição</label><textarea id="descricao" name="descricao" maxlength="255" rows="3"><?= htmlspecialchars((string) ($editar['descricao'] ?? ''), ENT_QUOTES, 'UTF-8') ?></textarea><div class="form-actions"><button class="button" type="submit"><?= $editando ? 'Salvar alterações' : 'Cadastrar produto' ?></button><?php if ($editando): ?><a class="button ghost" href="?route=/produtos">Cancelar</a><?php endif; ?></div></form></article>
<article class="card list-card"><div class="list-title"><h2>Produtos cadastrados</h2><span><?= count($produtos) ?> registro(s)</span></div><?php if (!$produtos): ?><p class="empty-state">Nenhum produto cadastrado.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Categoria</th><th>Un.</th><th>Mínimo</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach ($produtos as $produto): ?><tr><td><strong><?= htmlspecialchars($produto['nome'], ENT_QUOTES, 'UTF-8') ?></strong><?php if (!empty($produto['descricao'])): ?><small><?= htmlspecialchars($produto['descricao'], ENT_QUOTES, 'UTF-8') ?></small><?php endif; ?></td><td><?= htmlspecialchars((string) ($produto['categoria_nome'] ?? '—'), ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($produto['unidade_medida'], ENT_QUOTES, 'UTF-8') ?></td><td><?= rtrim(rtrim(number_format((float) $produto['estoque_minimo'], 3, ',', '.'), '0'), ',') ?></td><td><span class="pill <?= $produto['ativo'] ? 'active' : 'inactive' ?>"><?= $produto['ativo'] ? 'Ativo' : 'Inativo' ?></span></td><td class="actions-cell"><a class="text-link" href="?route=/produtos&id=<?= (int) $produto['id'] ?>">Editar</a><form method="post" action="?route=/produtos/status"><input type="hidden" name="id" value="<?= (int) $produto['id'] ?>"><input type="hidden" name="ativo" value="<?= $produto['ativo'] ? 0 : 1 ?>"><button class="link-button <?= $produto['ativo'] ? 'danger-text' : '' ?>" type="submit"><?= $produto['ativo'] ? 'Desativar' : 'Ativar' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></article></section>
